<template>
  <section id="noteworthy-trial" class="nw-panel nw-trial" aria-label="Trial and data choices">
    <div class="nw-trial-heading"><div><p class="eyebrow">Your practice. Your data.</p><h2>{{ state?.state==='deleted'?'Your NoteWorthy workspace was deleted.':state?.commercialActive?'Your NoteWorthy plan is active.':state?.trialStartedAt?`${state.daysRemaining} days left in your free trial`:'30 days free. No card required.' }}</h2></div><button type="button" :disabled="busy" @click="load">Refresh status</button></div>
    <p v-if="error" class="nw-alert nw-alert-error" role="alert">{{ error }}</p><p v-if="notice" class="nw-alert" role="status">{{ notice }}</p>
    <template v-if="state"><p v-if="!state.trialStartedAt&&!state.deletedAt">Your trial starts when FundThred approves your practice for real billing-report uploads. You can set up rates and complete agreements first.</p><p v-if="state.trialEndsAt&&!state.commercialActive">Trial ends <strong>{{ displayDate(state.trialEndsAt) }}</strong>. {{ state.state==='retained'?'Your workspace is read-only during your selected retention period.':'' }}</p>
      <p v-if="state.scheduledDeletionAt&&!state.commercialActive&&!state.deletedAt" class="nw-trial-deadline">{{ state.deletionRequestedAt?'Deletion requested':'Automatic deletion scheduled' }}: <strong>{{ displayDate(state.scheduledDeletionAt) }}</strong>. {{ state.deletionRequestedAt?'Your data is locked while cleanup runs.':'Continue with FundThred or save a different retention choice before this time.' }}</p>
      <p v-if="state.deletionJob?.status==='review_required'||state.deletionJob?.status==='retry'" role="status">Cleanup needs attention and is not complete. FundThred can review the deletion receipt; your data stays locked.</p><p v-if="state.deletedAt" role="status">Active workspace data was removed on {{ displayDate(state.deletedAt) }}. Your shared sign-in and required signed agreements are separate.</p>
      <template v-if="!state.deletionRequestedAt&&!state.deletedAt"><form v-if="!state.commercialActive" @submit.prevent="savePolicy"><label>After the trial, if I haven’t continued<select v-model.number="retentionDays" @change="policyDirty=true"><option :value="0">Delete my trial workspace at the end of the trial</option><option :value="7">Keep it read-only for 7 more days, then delete</option><option :value="30">Keep it read-only for 30 more days, then delete</option><option :value="90">Keep it read-only for 90 more days, then delete</option></select></label><label class="nw-trial-check"><input v-model="acknowledged" @change="policyDirty=true" type="checkbox" required /> I understand this choice covers the imported data, roster, saved payroll and workspace messages, and that deletion is permanent.</label><button type="submit" :disabled="busy">{{ state.policyAccepted?'Save my data choice':'Confirm trial & data choices' }}</button></form>
      <div class="nw-inline-actions"><button v-if="!state.commercialActive" type="button" @click="$emit('contact','continue')">Continue with FundThred</button><button type="button" @click="showWipe=true">Wipe my NoteWorthy data</button><a href="https://auricwell.com" target="_blank" rel="noopener noreferrer">Explore Auricwell’s EHR →</a></div><p v-if="state.continuationRequestedAt" class="nw-small">Your request to continue is saved. We’ll confirm your plan before billing; data is held for at least 7 days after the trial while that is reviewed.</p></template>
      <p class="nw-small">{{ state.deletionNotice }}</p>
    </template>
    <div v-if="showWipe" class="nw-wipe-overlay" @keydown.esc="!busy && (showWipe=false)"><section role="dialog" aria-modal="true" aria-labelledby="nw-wipe-title" class="nw-wipe-dialog" ref="wipeDialog" @keydown.tab="trapFocus"><h2 id="nw-wipe-title">Permanently wipe this workspace?</h2><p>This removes saved payroll, imported billing rows, roster records, invitations, messages, and stored files. Download the records you need first. An Auricwell EHR workspace cannot be erased with this control.</p><form @submit.prevent="wipe"><label>Type the practice name: {{ practiceName }}<input v-model="confirmationName" required :placeholder="practiceName" autocomplete="off" /></label><label class="nw-trial-check"><input v-model="wipeConfirmed" type="checkbox" required /> I’m authorized to permanently delete this practice’s NoteWorthy data.</label><div class="nw-inline-actions"><button type="button" :disabled="busy" @click="showWipe=false">Cancel</button><button class="nw-wipe-button" :disabled="busy||confirmationName!==practiceName||!wipeConfirmed">{{ busy?'Requesting deletion…':'Permanently wipe my data' }}</button></div></form></section></div>
  </section>
</template>
<script setup>
import {onMounted,onBeforeUnmount,nextTick,ref,watch} from 'vue';
import api from '../../services/api';
const props=defineProps({agencyId:{type:[Number,String],required:true},practiceName:{type:String,required:true}}),emit=defineEmits(['state','contact']);
const policyDirty=ref(false),wipeDialog=ref(null);
const state=ref(null),retentionDays=ref(0),acknowledged=ref(false),busy=ref(false),error=ref(''),notice=ref(''),showWipe=ref(false),confirmationName=ref(''),wipeConfirmed=ref(false);
const config={headers:{'X-Noteworthy-Request':'1'},skipGlobalLoading:true};let timer,generation=0,lastLoaded=0;
const displayDate=value=>new Date(String(value).replace(' ','T')+(/Z$|[+-]\d\d:\d\d$/.test(value)?'':'Z')).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'});
function apply(data){state.value=data;if(!policyDirty.value){retentionDays.value=data.retentionDays || 0;acknowledged.value=!!data.policyAccepted;}emit('state',data);}
async function load(){lastLoaded=Date.now();const current=++generation;try{const{data}=await api.get(`/noteworthy/practices/${props.agencyId}/lifecycle`,{skipGlobalLoading:true});if(current===generation)apply(data);}catch(e){if(current===generation)error.value=e.response?.data?.error?.message || 'Trial status could not be loaded.';}}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn();}catch(e){error.value=e.response?.data?.error?.message || 'We could not confirm that change.';}finally{busy.value=false;}}
function savePolicy(){const agency=props.agencyId;return run(async()=>{const {data}=await api.put(`/noteworthy/practices/${agency}/data-choices`,{retentionDays:retentionDays.value,acknowledged:acknowledged.value},config);if(agency!==props.agencyId)return;policyDirty.value=false;apply(data);notice.value='Your trial and data-retention choices are saved.';});}
function wipe(){const agency=props.agencyId;return run(async()=>{const {data}=await api.post(`/noteworthy/practices/${agency}/wipe`,{practiceName:confirmationName.value,confirmed:wipeConfirmed.value},config);if(agency!==props.agencyId)return;apply(data);showWipe.value=false;notice.value='Deletion requested. The cleanup receipt will show when it is complete.';});}
function trapFocus(event){const elements=[...wipeDialog.value.querySelectorAll('input,button,a,select,textarea')].filter(el=>!el.disabled);if(!elements.length)return;const first=elements[0],last=elements.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}
watch(showWipe,async open=>{if(open){confirmationName.value='';wipeConfirmed.value=false;await nextTick();wipeDialog.value?.querySelector('input')?.focus();}});
watch(()=>props.agencyId,()=>{generation++;state.value=null;error.value='';showWipe.value=false;confirmationName.value='';wipeConfirmed.value=false;policyDirty.value=false;load();});
onMounted(()=>{load();timer=setInterval(()=>{if(!document.hidden&&!busy.value&&((state.value?.deletionRequestedAt&&!state.value?.deletedAt)||Date.now()-lastLoaded>60000))load();},5000);});onBeforeUnmount(()=>{generation++;clearInterval(timer);});
</script>
<style scoped>
.nw-trial{margin-bottom:24px;border-top:4px solid #079780}.nw-trial-heading{display:flex;justify-content:space-between;gap:20px;align-items:start}.nw-trial h2{font-size:22px}.nw-trial form{max-width:800px}.nw-trial-check{display:flex!important;flex-direction:row!important;align-items:start;line-height:1.7}.nw-trial-check input{margin-top:5px;flex-shrink:0}.nw-trial-deadline{padding:14px;border-radius:9px;background:#fff5df}.nw-trial .nw-inline-actions{margin-top:20px}.nw-wipe-overlay{position:fixed;inset:0;background:#071938aa;z-index:1200;display:grid;place-items:center;padding:20px;overflow:auto}.nw-wipe-dialog{background:white;border-radius:18px;padding:28px;max-width:650px;width:100%;max-height:90vh;overflow:auto}.nw-wipe-button{background:#a52f3b!important;color:white!important;border-color:#a52f3b!important}.nw-wipe-dialog input{width:100%}.nw-wipe-dialog input[type=checkbox]{width:auto}@media(max-width:650px){.nw-trial-heading{flex-direction:column}}
</style>
